SELECT

FROM MonitorWalletAssetFlows a WHERE 1 = 1 

    AND a.accountId = #{accountId}


    AND a.currency LIKE CONCAT('%',#{currency}, '%')
    /** AND a.currency = #{currency} */


    AND a.lastMonitorTime = #{lastMonitorTime}


    AND a.monitorStatus = #{monitorStatus}


    AND a.remark LIKE CONCAT('%',#{remark}, '%')
    /** AND a.remark = #{remark} */


    AND a.createTime = #{createTime}


    AND a.updateTime = #{updateTime}

order by a.createTime desc

SELECT

FROM MonitorWalletAssetFlows a
where a.accountId = #{accountId} AND a.currency = #{currency}
